# COMMAND ----------

import os

import mlflow
from databricks.sdk import WorkspaceClient
from mlflow.entities import AssessmentSource

dbutils.widgets.dropdown("action", "ask", ["ask", "log_verdicts"])  # noqa: F821
dbutils.widgets.dropdown("question_set", "benchmark", ["benchmark", "heldout_2", "heldout_3", "heldout_4", "heldout_5", "heldout_6"])  # noqa: F821
dbutils.widgets.text("run_name", "")  # noqa: F821
dbutils.widgets.text("space_title", "Approval Rate Copilot")  # noqa: F821
dbutils.widgets.text("experiment", "")  # noqa: F821
dbutils.widgets.text("graded_path", "")  # noqa: F821
args = {k: dbutils.widgets.get(k).strip() for k in  # noqa: F821
        ("action", "question_set", "run_name", "space_title", "experiment", "graded_path")}
w = WorkspaceClient()
api = w.api_client
experiment = args["experiment"] or f"/Users/{w.current_user.me().user_name}/approval-copilot-evals"
RUNS_DIR = "/Volumes/workspace/approval_copilot/landing/evals/runs"

# COMMAND ----------

if args["action"] == "ask":
    spaces = [s for s in api.do("GET", "/api/2.0/genie/spaces").get("spaces", [])
              if s.get("title") == args["space_title"]]
    assert len(spaces) == 1, f"expected one Genie space titled {args['space_title']!r}, found {len(spaces)}"
    run_name = args["run_name"] or f"{args['question_set']} {datetime.date.today().isoformat()}"
    result = run_eval(api, spaces[0]["space_id"], args["question_set"], QUESTIONS[args["question_set"]],
                      run_name, experiment, check, mlflow)
    os.makedirs(RUNS_DIR, exist_ok=True)
    path = f"{RUNS_DIR}/{re.sub(r'[^A-Za-z0-9_-]+', '_', run_name)}.json"
    with open(path, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=1, default=str)
    summary = {"saved_to": path, "mlflow_run_id": result["mlflow_run_id"], "metrics": result["metrics"]}
else:
    graded = json.load(open(args["graded_path"], encoding="utf-8"))
    mlflow.set_experiment(experiment)
    summary = log_verdicts(graded, mlflow, AssessmentSource)
print(summary)
dbutils.notebook.exit(json.dumps(summary, default=str))  # noqa: F821
